from taf.nms.nom.schemas.base import SchemaObject, SchemaObjects, SchemaField


class OperationFeedbackResponse(SchemaObject):
    operation_id = SchemaField(name="operation_id")
    timestamp = SchemaField(name="timestamp")
    type = SchemaField(name="type")
    message = SchemaField(name="message")
    details = SchemaField(name="details")
    object_dn = SchemaField(name="object_dn")

    def __init__(self, operation_id, timestamp, type, message, details, object_dn):
        self.operation_id = operation_id
        self.timestamp = timestamp
        self.type = type
        self.message = message
        self.details = details
        self.object_dn = object_dn

        super(OperationFeedbackResponse, self).__init__()


class OperationFeedbackResponses(SchemaObjects):
    schema = OperationFeedbackResponse
